cd /testbed && python3 - <<'PY'
import os, pathlib, subprocess, tempfile, time
root = pathlib.Path(tempfile.mkdtemp(prefix='acl-load-repro-', dir='/tmp'))
(root / 'users.acl').write_text('user foo on #551a821992d8592d71c26a4989e26ce1d39e90ba3c20e3eaf99eed4a2e64251f +@all ~* resetchannels &*\n')
procs = []
def cli(port, *args):
    return subprocess.run(['src/valkey-cli', '-p', str(port), *args], capture_output=True, text=True, timeout=5)
try:
    for port, extra in [(17779, []), (17780, ['--replicaof', '127.0.0.1', '17779'])]:
        log = open(root / f'{port}.log', 'w')
        proc = subprocess.Popen(['src/valkey-server', '--port', str(port), '--bind', '127.0.0.1', '--aclfile', str(root / 'users.acl'), '--save', '', '--appendonly', 'no', '--dir', str(root), '--repl-diskless-sync-delay', '0', *extra], stdout=log, stderr=subprocess.STDOUT)
        procs.append(proc)
        log.close()
        for _ in range(100):
            if cli(port, 'ping').stdout.strip() == 'PONG': break
            if proc.poll() is not None: raise RuntimeError((root / f'{port}.log').read_text())
            time.sleep(.05)
        else: raise RuntimeError('server did not start')
    for _ in range(100):
        if 'master_link_status:up' in cli(17780, 'info', 'replication').stdout: break
        time.sleep(.1)
    else: raise RuntimeError('replication did not connect')
    print('REPRO_DIR:', root)
    print('primary ACL LOAD:', cli(17779, 'acl', 'load').stdout.strip())
    result = cli(17780, 'acl', 'load')
    print('replica ACL LOAD:', repr(result.stdout), repr(result.stderr), 'exit:', result.returncode)
    time.sleep(.5)
    print('replica process exit:', procs[1].poll())
    text = (root / '17780.log').read_text()
    start = text.find('===')
    print(text[start:start+18000] if start >= 0 else text[-12000:])
finally:
    for proc in procs:
        if proc.poll() is None:
            proc.terminate()
            try: proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill(); proc.wait()
PY

