import pathlib, subprocess, time
root = pathlib.Path('/tmp/acl-load-repro-ei6t53_r')
procs = []
def cli(port, *args):
    result = subprocess.run(['src/valkey-cli', '-p', str(port), *args], capture_output=True, text=True, timeout=5)
    if result.returncode: raise RuntimeError(result.stderr)
    return result.stdout.strip()
try:
    for port, extra in [(17779, []), (17780, ['--replicaof', '127.0.0.1', '17779'])]:
        log = open(root / f'fixed-{port}.log', 'w')
        proc = subprocess.Popen(['src/valkey-server', '--port', str(port), '--bind', '127.0.0.1', '--aclfile', str(root / 'users.acl'), '--save', '', '--appendonly', 'no', '--dir', str(root), '--repl-diskless-sync-delay', '0', *extra], stdout=log, stderr=subprocess.STDOUT)
        procs.append(proc)
        log.close()
        for _ in range(100):
            result = subprocess.run(['src/valkey-cli', '-p', str(port), 'ping'], capture_output=True, text=True)
            if result.stdout.strip() == 'PONG': break
            if proc.poll() is not None: raise RuntimeError('server exited')
            time.sleep(.05)
        else: raise RuntimeError('server did not start')
    for _ in range(100):
        if 'master_link_status:up' in cli(17780, 'info', 'replication'): break
        time.sleep(.1)
    else: raise RuntimeError('replication did not connect')
    for port in (17779, 17780):
        assert cli(port, 'acl', 'load') == 'OK'
        assert cli(port, 'acl', 'users').splitlines() == ['default', 'foo']
        print(f'{port}: ACL LOAD OK; users: default, foo')
    for i in range(3):
        assert cli(17780, 'acl', 'load') == 'OK'
        assert cli(17779, 'set', 'acl-load-key', str(i)) == 'OK'
        assert cli(17779, 'wait', '1', '5000') == '1'
        assert cli(17780, 'get', 'acl-load-key') == str(i)
    assert all(proc.poll() is None for proc in procs)
    print('Original reproduction fixed; repeated ACL LOAD preserves replication')
finally:
    for proc in procs:
        if proc.poll() is None:
            proc.terminate()
            try: proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill(); proc.wait()
